import fs from 'node:fs';
const files = fs.readdirSync('.').filter((f) => f.endsWith('.jsonl'));
const sessions = {};
for (const f of files) {
  const id = f.slice(11, 19);
  const s = (sessions[id] ??= { date: f.slice(0, 10), in: 0, cw: 0, cr: 0, out: 0, models: new Set(), files: 0 });
  s.files++;
  const seen = new Map();
  for (const line of fs.readFileSync(f, 'utf8').split('\n')) {
    if (!line) continue;
    let e; try { e = JSON.parse(line); } catch { continue; }
    const m = e.message;
    if (e.type !== 'assistant' || !m?.usage) continue;
    if (m.model && m.model !== '<synthetic>') s.models.add(m.model);
    seen.set(m.id ?? e.uuid, m.usage); // last entry per message id has the final usage
  }
  for (const u of seen.values()) {
    s.in += u.input_tokens ?? 0; s.cw += u.cache_creation_input_tokens ?? 0;
    s.cr += u.cache_read_input_tokens ?? 0; s.out += u.output_tokens ?? 0;
  }
}
for (const [id, s] of Object.entries(sessions).sort((a, b) => a[1].date.localeCompare(b[1].date)))
  console.log(id, s.date, s.files, [...s.models].join(','), s.in, s.cw, s.cr, s.out);
