    s=open(path).read(); assert old in s,(path,old); open(path,'w').write(s.replace(old,new,1))
p='scripts/archive-session.mjs'
sub(p, " *   <out>/README.md                        regenerated index\n",
" *   <out>/README.md                        regenerated index; titles from <out>/labels.json\n *                                          ({ \"<first 8 chars of id>\": \"label\" }) win\n")
sub(p, """export function renderIndex(outDir) {
  const rows = readdirSync(outDir)""", """export function renderIndex(outDir) {
  const labelsFile = path.join(outDir, 'labels.json');
  const labels = existsSync(labelsFile) ? JSON.parse(readFileSync(labelsFile, 'utf8')) : {};
  const rows = readdirSync(outDir)""")
sub(p, "        title: md.match(/^# (.+)$/m)?.[1] ?? '',", "        title: labels[m[2].slice(0, 8)] ?? md.match(/^# (.+)$/m)?.[1] ?? '',")
EOF
node --test scripts/__tests__/archive-session.test.mjs 2>&1 | grep -E "^# (pass|fail)|not ok"

